use std::collections::BTreeMap;

pub type Scope = BTreeMap<String, i64>;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Expr {
    Number(i64),
    Name(String),
    Add(Box<Expr>, Box<Expr>),
    Multiply(Box<Expr>, Box<Expr>),
    Assign(String, Box<Expr>),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EvalError {
    UnknownName(String),
    Overflow,
    EmptyName,
}

pub fn eval(expr: &Expr, scope: &mut Scope) -> Result<i64, EvalError> {
    match expr {
        Expr::Number(value) => Ok(*value),
        Expr::Name(name) => scope
            .get(name)
            .copied()
            .ok_or_else(|| EvalError::UnknownName(name.clone())),
        Expr::Add(left, right) => {
            let left = eval(left, scope)?;
            let right = eval(right, scope)?;
            Ok(left.wrapping_add(right))
        }
        Expr::Multiply(left, right) => {
            let left = eval(left, scope)?;
            let right = eval(right, scope)?;
            left.checked_mul(right).ok_or(EvalError::Overflow)
        }
        Expr::Assign(name, value) => {
            if name.is_empty() {
                return Err(EvalError::EmptyName);
            }
            let evaluated = eval(value, scope)?;
            scope.insert(name.clone(), evaluated);
            Ok(evaluated)
        }
    }
}

