#[path = "solution.rs"]
mod solution;

use solution::{eval, EvalError, Expr, Scope};

fn boxed(expr: Expr) -> Box<Expr> {
    Box::new(expr)
}

fn assert_traits<T: std::fmt::Debug + Clone + PartialEq + Eq>() {}

#[test]
fn public_enums_have_required_traits() {
    assert_traits::<Expr>();
    assert_traits::<EvalError>();
}

#[test]
fn numbers_and_names_evaluate_without_mutating_scope() {
    let mut scope = Scope::new();
    scope.insert("x".to_string(), 12);
    let before = scope.clone();
    assert_eq!(eval(&Expr::Number(-7), &mut scope), Ok(-7));
    assert_eq!(eval(&Expr::Name("x".to_string()), &mut scope), Ok(12));
    assert_eq!(scope, before);
}

#[test]
fn unknown_names_are_reported_exactly_and_left_operand_is_first() {
    let mut scope = Scope::new();
    assert_eq!(eval(&Expr::Name("missing".to_string()), &mut scope), Err(EvalError::UnknownName("missing".to_string())));
    let expr = Expr::Add(
        boxed(Expr::Name("left".to_string())),
        boxed(Expr::Name("right".to_string())),
    );
    assert_eq!(eval(&expr, &mut scope), Err(EvalError::UnknownName("left".to_string())));
    assert!(scope.is_empty());
}

#[test]
fn checked_addition_and_multiplication_detect_overflow() {
    let mut scope = Scope::new();
    let add = Expr::Add(boxed(Expr::Number(i64::MAX)), boxed(Expr::Number(1)));
    let multiply = Expr::Multiply(boxed(Expr::Number(i64::MIN)), boxed(Expr::Number(-1)));
    assert_eq!(eval(&add, &mut scope), Err(EvalError::Overflow));
    assert_eq!(eval(&multiply, &mut scope), Err(EvalError::Overflow));
    assert!(scope.is_empty());

    let valid = Expr::Multiply(
        boxed(Expr::Add(boxed(Expr::Number(2)), boxed(Expr::Number(3)))),
        boxed(Expr::Number(4)),
    );
    assert_eq!(eval(&valid, &mut scope), Ok(20));
}

#[test]
fn assignment_inserts_replaces_and_returns_the_value() {
    let mut scope = Scope::new();
    let first = Expr::Assign("answer".to_string(), boxed(Expr::Number(41)));
    assert_eq!(eval(&first, &mut scope), Ok(41));
    assert_eq!(scope.get("answer"), Some(&41));

    let replace = Expr::Assign(
        "answer".to_string(),
        boxed(Expr::Add(boxed(Expr::Number(20)), boxed(Expr::Number(22)))),
    );
    assert_eq!(eval(&replace, &mut scope), Ok(42));
    assert_eq!(scope.get("answer"), Some(&42));
}

#[test]
fn failed_assignment_preserves_its_target_binding() {
    let mut scope = Scope::new();
    scope.insert("target".to_string(), 9);
    let expr = Expr::Assign(
        "target".to_string(),
        boxed(Expr::Add(boxed(Expr::Number(i64::MAX)), boxed(Expr::Number(1)))),
    );
    assert_eq!(eval(&expr, &mut scope), Err(EvalError::Overflow));
    assert_eq!(scope.get("target"), Some(&9));

    let unknown = Expr::Assign("new".to_string(), boxed(Expr::Name("absent".to_string())));
    assert_eq!(eval(&unknown, &mut scope), Err(EvalError::UnknownName("absent".to_string())));
    assert!(!scope.contains_key("new"));
}

#[test]
fn empty_assignment_name_is_rejected_without_evaluating_or_mutating() {
    let mut scope = Scope::new();
    scope.insert("kept".to_string(), 3);
    let before = scope.clone();
    let expr = Expr::Assign(
        String::new(),
        boxed(Expr::Assign("side_effect".to_string(), boxed(Expr::Number(8)))),
    );
    assert_eq!(eval(&expr, &mut scope), Err(EvalError::EmptyName));
    assert_eq!(scope, before);
}

